-- reviews (room_id NULL = review of the whole hostel)
INSERT INTO reviews (review_id, hostel_id, room_id, user_id, rating, title, comment, status, created_at) VALUES
  (  1,  1, 1   ,  3, 4, 'Good value for first year',
       'Six of us in one room sounds like a lot, but the room is big and the cots are spaced out. Fans are fine except in April and May. You get to know your batchmates fast.', 'approved', NOW() - INTERVAL 150 DAY),
  (  2,  1, NULL,  4, 3, 'Old block, decent upkeep',
       'One of the older blocks, so the bathrooms show their age, but they are cleaned twice a day. Wi-Fi is weak on the top floor after 10 pm.', 'approved', NOW() - INTERVAL 120 DAY),
  (  3,  1, 3   ,  6, 4, '4-bed AC is worth the extra',
       'Paid around ₹30k more per year for the AC 4-bed and it was worth it in summer. The room is a bit cramped with four study tables, though.', 'approved', NOW() - INTERVAL 95 DAY),
  (  4,  1, NULL,  8, 3, 'Mess is okay, laundry is slow',
       'The veg mess menu repeats every week; the non-veg mess is better on Wednesdays and Sundays. Laundry takes three to four days to come back.', 'approved', NOW() - INTERVAL 70 DAY),
  (  5,  1, 2   , 10, 4, 'Quiet floor, short walk to class',
       'The 4-bed non-AC rooms on the second floor are quiet and the walk to the academic blocks is short. Power cuts are covered by backup.', 'approved', NOW() - INTERVAL 40 DAY),
  (  6,  1, NULL,  3, 2, 'Water problem last week',
