-- avg_rating = average of the approved reviews (the WHERE on the key also satisfies MySQL Workbench safe-update mode)
UPDATE hostels h
SET h.avg_rating = (
  SELECT COALESCE(ROUND(AVG(r.rating), 1), 0)
  FROM reviews r
  WHERE r.hostel_id = h.hostel_id
    AND r.status = 'approved'
)
WHERE h.hostel_id > 0;
